import React, { useEffect, useState } from 'react';
import axios from 'axios';
import styles from './BookList.module.css';

function BookList({ user }) {
  const [books, setBooks] = useState([]);
  const [error, setError] = useState('');

  useEffect(() => {
    axios.get('http://localhost:5000/api/books')
      .then(res => setBooks(res.data))
      .catch(() => setError('Failed to fetch books'));
  }, []);

  const requestBook = async (bookId) => {
    try {
      await axios.post('http://localhost:5000/api/requests', {
        studentId: user._id,
        bookId
      });
      alert('Request sent!');
    } catch {
      alert('Failed to request book');
    }
  };

  return (
    <div className={styles.container}>
      <div className={styles.title}>Available Books</div>
      {error && <p style={{ color: 'red' }}>{error}</p>}
      <ul className={styles.list}>
        {books.map(book => (
          <li className={styles.item} key={book._id}>
            <span>{book.title} <span style={{color:'#888'}}>by</span> {book.author}</span>
            {user?.role === 'student' && book.available && (
              <button className={styles.button} onClick={() => requestBook(book._id)}>Request</button>
            )}
          </li>
        ))}
      </ul>
    </div>
  );
}

export default BookList;
